#!/usr/bin/env python3
"""Find duplicated Source entries across the local worktree's episode files."""
import re, glob, collections

WT = "/tmp/wt-main-ross"
seen = collections.defaultdict(list)
for f in sorted(glob.glob(WT + "/S0*/E*.md")):
    for m in re.finditer(r"^Source: (friend/\w+) @ ([0-9a-f]{40})", open(f).read(), re.M):
        seen[m.group(2)].append(f)
dups = {s: v for s, v in seen.items() if len(v) > 1}
print("total source entries:", sum(len(v) for v in seen.values()))
print("unique shas:", len(seen))
print("duplicated shas:", len(dups))
for s, v in dups.items():
    print("  DUP", s, v)

