def filed_map():
    # Dedup against the LOCAL worktree files, not origin/main: a stale remote ref
    # makes this re-file entries that are already on disk but not yet pushed.
    filed = collections.defaultdict(list)
    for path in sorted(glob.glob(os.path.join(WT, "S*", "E*.md"))):
        rel = os.path.relpath(path, WT)
        for m in re.finditer(r"^Source: (friend/\w+) @ ([0-9a-f]{40})", open(path).read(), re.M):
            filed[m.group(2)].append(rel)
    return filed

