#!/usr/bin/env python3
"""Reorder episode entries so that each utterance follows the one it replies to,
and otherwise follow commit time then full SHA.

Uses Kahn's algorithm: among the entries whose Reply-To target has already been
placed, the one with the earliest commit time goes next. This keeps the
documented ordering rule (commit time, then SHA) while never placing a reply
before the beat it answers.
"""
import re, subprocess, glob, os, sys, heapq

REPO = "/home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill"
WT = "/tmp/wt-main-ross"

def git(*a):
    return subprocess.run(["git", "-C", REPO] + list(a), capture_output=True, text=True).stdout

_cache = {}
def meta(sha):
    if sha not in _cache:
        raw = git("show", "-s", "--format=%cI%x00%B", sha)
        cdate, body = raw.split("\x00", 1)
        r = re.search(r"^Reply-To:\s*(\S+)", body, re.M)
        _cache[sha] = (cdate, r.group(1) if r else "none")
    return _cache[sha]

ENTRY = re.compile(
    r"^\*\*([^*]+)\*\* \(([^)]*)\)\n\nSource: (friend/\w+) @ ([0-9a-f]{40})\n\n(.*?)\n(?=\n|\Z)",
    re.M | re.S)

def reorder(path):
    text = open(path).read()
    entries = []
    for m in ENTRY.finditer(text):
        entries.append(dict(speaker=m.group(1), ts=m.group(2), branch=m.group(3),
                            sha=m.group(4), body=m.group(5), start=m.start(), end=m.end()))
    if not entries:
        return 0
    shas = [e["sha"] for e in entries]
    pos = {h: i for i, h in enumerate(shas)}
    # dependency: entry must come after its reply-to target, if the target is present
    deps = {}
    children = {h: [] for h in shas}
    indeg = {h: 0 for h in shas}
    for e in entries:
        cdate, reply = meta(e["sha"])
        e["cdate"] = cdate
        if reply != "none" and reply in pos:
            deps[e["sha"]] = reply
            children[reply].append(e["sha"])
            indeg[e["sha"]] += 1
        else:
            deps[e["sha"]] = None
    heap = []
    for h in shas:
        if indeg[h] == 0:
            heapq.heappush(heap, (meta(h)[0], h))
    out = []
    while heap:
        _, h = heapq.heappop(heap)
        out.append(h)
        for c in children[h]:
            indeg[c] -= 1
            if indeg[c] == 0:
                heapq.heappush(heap, (meta(c)[0], c))
    if len(out) != len(shas):
        # cycle: fall back to plain commit-time order
        out = sorted(shas, key=lambda h: (meta(h)[0], h))
    if out == shas:
        return 0
    bysha = {e["sha"]: e for e in entries}
    # rebuild: replace the entry region wholesale
    first, last = entries[0]["start"], entries[-1]["end"]
    blocks = []
    for h in out:
        e = bysha[h]
        blocks.append(f"**{e['speaker']}** ({e['ts']})\n\nSource: {e['branch']} @ {e['sha']}\n\n{e['body']}\n")
    new = text[:first] + "\n".join(blocks).rstrip("\n") + "\n" + text[last:]
    new = re.sub(r"\n{3,}", "\n\n", new)
    open(path, "w").write(new)
    return len(entries)

changed = 0
for path in sorted(glob.glob(os.path.join(WT, "S*", "E*.md"))):
    n = reorder(path)
    if n:
        changed += 1
        print(f"{os.path.relpath(path, WT)}: reordered {n} entries")
print("files changed:", changed)

